import{_ as t,o as s,c as i,a3 as a}from"./chunks/framework.vDgOMd_y.js";const u=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"en/guides/getting-started.md","filePath":"en/guides/getting-started.md"}'),n={name:"en/guides/getting-started.md"};function o(l,e,r,d,h,p){return s(),i("div",null,[...e[0]||(e[0]=[a(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /kimiteam/docs/en/guides/getting-started.md for this page in Markdown format</div><h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><h2 id="what-is-kimi-code-cli" tabindex="-1">What is Kimi Code CLI <a class="header-anchor" href="#what-is-kimi-code-cli" aria-label="Permalink to &quot;What is Kimi Code CLI&quot;">​</a></h2><p>Kimi Code CLI is an AI agent that runs in the terminal, helping you carry out software development tasks and day-to-day terminal operations — reading and modifying code, running shell commands, searching files, fetching web pages, and autonomously planning and adjusting its next steps based on feedback as it works.</p><p>It fits scenarios such as:</p><ul><li><strong>Writing and modifying code</strong>: implementing new features, fixing bugs, completing refactors</li><li><strong>Understanding a project</strong>: exploring an unfamiliar codebase and answering questions about architecture and implementation</li><li><strong>Automating tasks</strong>: batch-processing files, running builds and tests, chaining multiple scripts together</li></ul><p>The CLI is written in TypeScript, distributed via npm, and runs on Node.js.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Two installation options are available: the official install script (recommended, no pre-installed Node.js required) and a global npm install.</p><div class="tip custom-block"><p class="custom-block-title">Before you install</p><p>Kimi Code CLI is a fully interactive TUI application. For the best visual experience, run it in a terminal with true-color and ligature support, such as <a href="https://sw.kovidgoyal.net/kitty/" target="_blank" rel="noreferrer">Kitty</a> or <a href="https://ghostty.org/" target="_blank" rel="noreferrer">Ghostty</a>.</p></div><h3 id="install-script-recommended" tabindex="-1">Install script (recommended) <a class="header-anchor" href="#install-script-recommended" aria-label="Permalink to &quot;Install script (recommended)&quot;">​</a></h3><ul><li><strong>macOS / Linux</strong>:</li></ul><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://code.kimi.com/kimi-code/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><ul><li><strong>Windows (PowerShell)</strong>:</li></ul><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">code.kimi.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kimi</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">code</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div><blockquote><p>On Windows, install <a href="https://gitforwindows.org/" target="_blank" rel="noreferrer">Git for Windows</a> before first launch. Kimi Code CLI uses the bundled Git Bash as its shell environment; if Git Bash is installed in a custom location, set <code>KIMI_SHELL_PATH</code> to the absolute path of <code>bash.exe</code>.</p></blockquote><p>The script automatically downloads the latest release, verifies the checksum, and places the <code>kimi</code> executable on your <code>PATH</code>.</p><h3 id="npm-installation" tabindex="-1">npm installation <a class="header-anchor" href="#npm-installation" aria-label="Permalink to &quot;npm installation&quot;">​</a></h3><p>Requires Node.js 22.19.0 or later:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @moonshot-ai/kimi-code</span></span></code></pre></div><p>Or with pnpm:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @moonshot-ai/kimi-code</span></span></code></pre></div><h2 id="upgrade-and-uninstall" tabindex="-1">Upgrade and uninstall <a class="header-anchor" href="#upgrade-and-uninstall" aria-label="Permalink to &quot;Upgrade and uninstall&quot;">​</a></h2><p>After installation, verify that the executable is ready:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p><strong>Upgrade</strong>: run <code>kimi upgrade</code> — the CLI checks for the latest version and presents update options. Choose <code>Install update now</code> to upgrade based on your current install source. You can also upgrade directly via the package manager:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @moonshot-ai/kimi-code@latest</span></span></code></pre></div><p><strong>Uninstall</strong>: if you installed via the script, delete the <code>kimi</code> executable. If you installed via npm:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @moonshot-ai/kimi-code</span></span></code></pre></div><h2 id="first-launch" tabindex="-1">First launch <a class="header-anchor" href="#first-launch" aria-label="Permalink to &quot;First launch&quot;">​</a></h2><p>Move into your project directory and run <code>kimi</code> to start the interactive UI:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span></span></code></pre></div><p>To run a single instruction without entering the interactive UI, use <code>-p</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Take a look at this project&#39;s directory structure&quot;</span></span></code></pre></div><p>To resume the previous session, add <code>-c</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span></span></code></pre></div><p>On first launch you need to configure an API source. In the interactive UI, enter <code>/login</code> to begin the login flow:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/login</span></span></code></pre></div><p><code>/login</code> opens a platform selector supporting two options:</p><ul><li><strong>Kimi Code (OAuth)</strong> — device-code flow; open the link on any device, sign in, and enter the code to authorize</li><li><strong>Kimi Platform API key</strong> — enter an API key from <code>platform.kimi.com</code> or <code>platform.kimi.ai</code></li></ul><p>To sign out, enter <code>/logout</code> to clear the current credentials.</p><div class="tip custom-block"><p class="custom-block-title">Using other AI providers</p><p>If you want to connect Anthropic, OpenAI, Google, or other providers, edit <code>~/.kimi-code/config.toml</code> directly to configure the API key. See <a href="./../configuration/providers.html">Providers and models</a> for details. For the full reference of all config options, see <a href="./../configuration/config-files.html">Configuration files</a>, <a href="./../configuration/env-vars.html">Environment variables</a>, and <a href="./../configuration/overrides.html">Configuration overrides</a>.</p></div><h2 id="your-first-conversation" tabindex="-1">Your first conversation <a class="header-anchor" href="#your-first-conversation" aria-label="Permalink to &quot;Your first conversation&quot;">​</a></h2><p>Once logged in, describe a task in natural language. A good starting point is to let Kimi Code CLI familiarize itself with the project:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Take a look at this project&#39;s directory structure and briefly describe what each directory is for.</span></span></code></pre></div><p>Kimi Code CLI automatically calls file-reading, search, and other tools to browse the relevant content before responding. Read-only operations are executed automatically by default without requiring confirmation. For operations that modify files or run shell commands, it asks for your confirmation before proceeding.</p><p>You can also describe a more concrete task directly:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Add a function in src/utils that converts any string to kebab-case, and add a unit test for it.</span></span></code></pre></div><p>Kimi Code CLI plans the steps, modifies the code, runs the tests, and tells you what it did at each step.</p><div class="tip custom-block"><p class="custom-block-title">Not sure what to do? Type <code>/help</code></p><p>Type <code>/help</code> at any time to open the built-in command and keyboard shortcut panel. Use <code>↑</code>/<code>↓</code> to browse and <code>Esc</code> to close. To exit, type <code>/exit</code>, press <code>Ctrl-C</code> twice, or press <code>Ctrl-D</code> with the input box empty.</p></div><h2 id="common-commands-and-keyboard-shortcuts" tabindex="-1">Common commands and keyboard shortcuts <a class="header-anchor" href="#common-commands-and-keyboard-shortcuts" aria-label="Permalink to &quot;Common commands and keyboard shortcuts&quot;">​</a></h2><p>For a first-time user, the following is all you need to know:</p><p><strong>Session commands</strong></p><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>/new</code></td><td>Start a new session, clearing the current context</td></tr><tr><td><code>/sessions</code></td><td>Browse session history and choose one to resume</td></tr><tr><td><code>/model</code></td><td>Switch the current model</td></tr><tr><td><code>/compact</code></td><td>Manually compress the context to free up tokens</td></tr><tr><td><code>/fork</code></td><td>Fork the current session into an independent copy with full history (you stay in the current session)</td></tr></tbody></table><p><strong>Most-used keyboard shortcuts</strong></p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Description</th></tr></thead><tbody><tr><td><code>Esc</code></td><td>Interrupt streaming output / close a popup</td></tr><tr><td><code>Ctrl-C</code></td><td>Interrupt output; press twice while idle to exit</td></tr><tr><td><code>Shift-Tab</code></td><td>Toggle Plan mode</td></tr><tr><td><code>Ctrl-S</code></td><td>Inject a message mid-stream without waiting for the current response to finish</td></tr><tr><td><code>Ctrl-O</code></td><td>Collapse / expand tool output and compaction summaries</td></tr></tbody></table><p>For the full list, type <code>/help</code> or visit <a href="./../reference/slash-commands.html">Slash commands reference</a> and <a href="./../reference/keyboard.html">Keyboard shortcuts</a>.</p><h2 id="where-data-is-stored" tabindex="-1">Where data is stored <a class="header-anchor" href="#where-data-is-stored" aria-label="Permalink to &quot;Where data is stored&quot;">​</a></h2><p>Kimi Code CLI stores its local data under <code>~/.kimi-code/</code> by default — config files, session records, logs, and the update cache. To move it elsewhere, point to a new path via the <code>KIMI_CODE_HOME</code> environment variable. For the full directory layout, see <a href="./../configuration/data-locations.html">Data locations</a> and <a href="./../configuration/env-vars.html">Environment variables</a>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./interaction.html">Interaction and input</a> — input box operations, approval flow, Plan mode, and YOLO mode explained</li><li><a href="./sessions.html">Sessions and context</a> — resuming sessions, compressing context, exporting sessions</li><li><a href="./use-cases.html">Common use cases</a> — prompt examples for typical tasks</li></ul>`,61)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
